#!/usr/bin/env python3
"""Measure missing primary native stages and prepare an isolated model task."""
import argparse,json,re
from pathlib import Path
from test_read_variants import ROOT,CN,measure,sha,save

def main():
    p=argparse.ArgumentParser();p.add_argument('--group',required=True);p.add_argument('--task-dir',type=Path,required=True);a=p.parse_args();g=ROOT/'benchmark/programs'/a.group;plan=json.loads((g/'evaluation-plan.json').read_text());variants={json.loads(p.read_text())['id']:json.loads(p.read_text()) for p in (g/'variants').glob('*/manifest.json')};out=ROOT/'benchmark/results'/a.group/'20261016-primary-native';rp=out/'receipt.json'
    cn=ROOT/variants[plan['primary_cn_variant']]['files']['cn']['path'];qcp=ROOT/variants[plan['primary_qcp_variant']]['files']['qcp']['path']
    if not rp.exists():
        cm=measure([CN,'verify',cn],out/'cn');save(out/'pending-receipt.json',{'cn':cm});assert cm['exit_code']==0,(ROOT/cm['stderr']).read_text()
        vc=out/'qcp/vc';qm=measure([ROOT/'bin/tespec-symexec','--input-file='+str(qcp),'--Json-output','--no-strategy-gen','--gen-and-backup','--coq-output-dir='+str(vc),'--no-logic-path','--disable-solver-info','--no-exec-info','-I'+str(ROOT/'runtime/qcip/QCP_examples/QCP_demos_human')],out/'qcp');save(out/'pending-receipt.json',{'cn':cm,'qcp':qm});assert qm['exit_code']==0,(ROOT/qm['stderr']).read_text();goals=list(vc.glob('*_goal.v'));assert len(goals)==1,goals;goal=goals[0]
        receipt={'schema':'tespec-group-primary-native/v1','program_group':a.group,'cn':cm,'qcp':qm,'cn_source':str(cn.relative_to(ROOT)),'cn_source_sha256':sha(cn),'qcp_source':str(qcp.relative_to(ROOT)),'qcp_source_sha256':sha(qcp),'goal':str(goal.relative_to(ROOT)),'goal_sha256':sha(goal),'native_binary_sha256':sha(ROOT/'bin/tespec-symexec'),'measurement_reason':'Historical exact-source records lack complete measured time/RSS and checked proof costs; preserve historical records and measure missing stages.'};save(rp,receipt);(out/'pending-receipt.json').unlink()
    else:receipt=json.loads(rp.read_text());goal=ROOT/receipt['goal'];assert sha(cn)==receipt['cn_source_sha256'] and sha(qcp)==receipt['qcp_source_sha256'] and sha(goal)==receipt['goal_sha256']
    task=a.task_dir;task.mkdir(parents=True,exist_ok=True);assert not(task/'Candidate.v').exists(),'Use a fresh isolated proof task';(task/'PrimaryQcpGoal.v').write_bytes(goal.read_bytes());text=goal.read_text();header=text.split('(*----- Function ')[0];interface=text.split('Module Type VC_Correct.')[1].split('End VC_Correct.')[0];obligations=re.findall(r'Axiom (\w+)\s*:\s*(\w+)\.',interface);assert obligations
    c='Require Import PrimaryQcpGoal.\n'+header+'\n'+''.join(f'Theorem primary_{name} : PrimaryQcpGoal.{name}.\nProof. Admitted.\n' for _,name in obligations)+'Module PrimaryCertificate : PrimaryQcpGoal.VC_Correct.\n'+''.join(f'Definition {field} := primary_{name}.\n' for field,name in obligations)+'End PrimaryCertificate.\n'+''.join(f'Print Assumptions primary_{name}.\n' for _,name in obligations)
    (task/'Candidate.v').write_text(c);(task/'prompt.txt').write_text('Fill every universally quantified Coq 8.20 proof in Candidate.v. Preserve imports, original statements, VC_Correct module implementation and Print Assumptions. PrimaryQcpGoal.v is immutable actual unbound QCP verification output. No Admitted/admit, new axioms, parameters, changed definitions or proof escapes. Edit Candidate.v only; do not read prior benchmark proof solutions, call models, or delegate. External compiler and independent kernel check are controller-owned. You may inspect runtime definitions through WSL Ubuntu-22.04 at /home/yangfp/teSpec/runtime/qcip/SeparationLogic. Simple entailments can be unfolded as predicates over heaps and solved with lia and propositional reasoning. Return briefly.\n\nActual immutable goal:\n'+text+'\nCandidate:\n'+c);print('Prepared',a.group,len(obligations),'universal obligations',flush=True)
if __name__=='__main__':main()
